import html
import baseline_content

def apply(pages,hero,section,card):
    baseline_content.apply(pages,hero,section,card)
    pages['']=('Business Acquisitions, Business Development & Portfolio Management','Ritch Ventures acquires, develops and manages businesses. We identify opportunities, structure transactions and develop commercial relationships to build long-term business value.',
        hero('Business Acquisitions | Business Development | Portfolio Management','We acquire, develop<br>and manage businesses.','We identify opportunities, structure transactions, develop commercial relationships and work to build long-term business value.','Discuss an Acquisition','/contact/?type=acquisition').replace('</div></div></section>','<a href="/contact/?type=business">Explore Business Opportunities</a></div></div></section>')
        +section('Three areas of focus.','''<div class="triptych"><article><p class="number">01 / ACQUISITIONS</p><h3>Explore a business ownership transition.</h3><p>Ritch Ventures identifies and evaluates businesses for full or partial acquisition.</p><p>Transaction structure depends on the opportunity; Lock Equity serves as the acquisition and investment vehicle.</p><a class="button" href="/contact/?type=acquisition">Discuss an Acquisition</a></article><article id="business-development"><p class="number">02 / BUSINESS DEVELOPMENT</p><h3>Build businesses and commercial relationships.</h3><p>We develop businesses, distribution relationships and strategic commercial opportunities.</p><p>Responsibilities are defined for each engagement.</p><a class="button" href="/contact/?type=business">Discuss a Business Opportunity</a></article><article id="portfolio-management"><p class="number">03 / PORTFOLIO MANAGEMENT</p><h3>Manage operating businesses.</h3><p>We work on operating priorities, commercial relationships and long-term business value where Ritch Ventures has an agreed ownership or management role.</p><a class="button" href="/our-businesses/">Explore Businesses &amp; Relationships</a></article></div>''')
        +section('Start with the opportunity.','''<p class="lead">Tell us about the business, transaction or commercial relationship you would like to discuss.</p><ol class="steps"><li><strong>Share an initial summary.</strong> Describe the business, opportunity and timing.</li><li><strong>Review the fit.</strong> Inquiries are reviewed before an initial conversation is offered.</li><li><strong>Determine next steps.</strong> Explore an acquisition, business development opportunity or defined management relationship.</li></ol>''')
        +section('Business opportunities, evaluated individually.','<div class="grid">'+card('Strategic commercial relationships','<p>We consider distribution, operating and other commercial relationships where responsibilities and objectives can be clearly defined.</p>','Discuss a Business Opportunity','/contact/?type=business')+card('Flexible business transitions','<p>Complete or partial acquisitions, majority transactions, appropriate minority investments, seller financing and earnouts may be considered.</p><p>Every opportunity is evaluated individually. No transaction is promised.</p>','Discuss an Acquisition','/contact/?type=acquisition')+'</div>')
        +section('Businesses, relationships and perspective.','''<div class="triptych"><article><h3>Businesses &amp; Relationships</h3><p>Explore business activities and commercial relationships across media, technology, risk and other areas.</p><a href="/our-businesses/">Explore Businesses &amp; Relationships</a></article><article><h3>Commercial and specialist relationships</h3><p>The responsible provider and any Ritch Ventures management role are defined for each engagement.</p><a href="/resources/">Resources &amp; Referrals</a></article><article><h3>Robert Ritch</h3><p>Robert’s separate personal brand covers business advisory, articles and commentary.</p><a href="https://robertritch.com/">Visit RobertRitch.com</a></article></div>'''))
    pages['robert-ritch']=('Robert Ritch','Robert Ritch leads Ritch Ventures. His separate personal brand supports business advisory, articles and commentary.',
        hero('Robert Ritch','Founder and principal<br>of Ritch Ventures.','Robert leads Ritch Ventures’ acquisition, business development and management activities. RobertRitch.com, operated through Substack, is his personal publishing and advisory destination.','Visit RobertRitch.com','https://robertritch.com/')
        +section('Business experience across different situations.','<p>Robert’s experience includes developing businesses, evaluating acquisitions, operating companies, investing, turnarounds and restructuring, capital strategy and business development.</p><p>Robert’s personal advisory work includes business assessments, ongoing advisory relationships, defined fixed-fee projects, capital strategy and business evaluations. He may refer owners to appropriate specialists. Scope, fees and responsibilities are agreed for each engagement.</p>')
        +section("The scale changes. The fundamentals don't.",'<p class="lead">Cash flow, profitability, sound capital decisions and a business that can operate effectively matter at every size.</p><p>Robert’s philosophy is to apply those business principles to the company in front of him—taking account of its resources, stage, constraints and owner’s objectives. The approach is practical: understand the issue before selecting a solution.</p>')
        +section('Articles, thought leadership and biography.','<p>RobertRitch.com remains Robert’s personal publishing and authority destination.</p><a class="button" href="https://robertritch.com/">Visit RobertRitch.com</a>'))
    pages['advisory']=('Business Advisory with Robert Ritch','Explore Robert Ritch’s separate personal advisory and publishing brand.',
        hero('Business Advisory','Work with Robert Ritch.','Robert Ritch’s personal advisory brand is separate from Ritch Ventures’ acquisition, business development and management platform. Visit RobertRitch.com for articles, business commentary and information about working with Robert.','Visit RobertRitch.com','https://robertritch.com/')
        +section('Advisory inquiries.','<p>Robert’s advisory work includes business assessments, ongoing advisory relationships, fixed-fee projects, capital strategy and evaluations. Inquiries are reviewed before a conversation is offered.</p><a class="button" href="https://robertritch.com/">Visit RobertRitch.com</a>'))
    t,d,b=pages['acquisitions']
    b=b.replace('Acquisitions & Lock Equity','Business Acquisitions').replace('Ritch Ventures evaluates established businesses and ownership transitions. Lock Equity may serve as the acquisition or investment vehicle.','Ritch Ventures identifies, evaluates and structures business acquisition opportunities. Lock Equity is the acquisition and investment vehicle; the participating entity and terms are determined for each transaction.')
    pages['acquisitions']=(t,'Explore business acquisitions and ownership transitions with Ritch Ventures and Lock Equity.',b)
    t,d,b=pages['lock-equity']
    b=b.replace('Ritch Ventures identifies and evaluates acquisition and investment opportunities for Lock Equity, which may serve as the acquisition or investment vehicle.','Lock Equity is the acquisition and investment vehicle. Ritch Ventures identifies and evaluates opportunities, develops commercial relationships and helps structure transactions. Participating entities, terms and responsibilities are determined for each opportunity.')
    pages['lock-equity']=(t,'Lock Equity is the acquisition and investment vehicle. Ritch Ventures identifies and evaluates opportunities.',b)
    t,d,b=pages['our-businesses']
    b=b.replace('Our Businesses','Businesses &amp; Relationships').replace('Businesses and relationships that move opportunities forward.','Business activities and commercial relationships.').replace('Ritch Ventures develops businesses, establishes distribution relationships and connects opportunities with specialized capabilities.','Explore the businesses, brands and commercial activities referenced in the Ritch Ventures platform.').replace('Business activities and brands.','Businesses and commercial activities.').replace('These activities include operating brands and distribution relationships. Listing a business does not imply ownership of an independent supplier or manufacturer. Each engagement identifies the responsible entity, scope and relevant relationship.','The entries below describe business activities. A listing alone does not establish ownership, control, management responsibility or an exclusive distribution agreement. The relevant entity and relationship are identified before an engagement begins.')
    pages['our-businesses']=('Businesses & Relationships','Explore business activities and commercial relationships referenced in the Ritch Ventures platform.',b)
    t,d,b=pages['resources']
    b=b.replace('Robert maintains relationships with specialists and helps business owners identify appropriate resources. He may facilitate introductions when there is a fit.','Ritch Ventures develops commercial relationships and connects business opportunities with specialized capabilities. The responsible provider and any coordination or management role are agreed for each engagement.').replace('href="/contact/">Apply to Work With Robert','href="/contact/?type=business">Discuss a Business Opportunity')
    b+=section('Personal business advisory.','<p>For personal business advisory, <a href="https://robertritch.com/">visit RobertRitch.com</a>.</p>')
    pages['resources']=(t,'Commercial and specialist relationships with clearly defined provider responsibilities.',b)
    pages['contact']=('Business Inquiries','Share an acquisition, investment, distribution or strategic commercial opportunity with Ritch Ventures.',
        hero('Business Inquiries','Tell us about the<br>business opportunity.','Share an acquisition, investment, distribution or strategic commercial opportunity. Inquiries are reviewed before an initial conversation is offered.','Explore Acquisitions','/acquisitions/')
        +'<section class="wrap section formwrap"><div class="actions form-switch"><button class="button" type="button" data-form="acquisition" aria-pressed="true">Acquisition Inquiry</button><button class="button" type="button" data-form="business" aria-pressed="false">Business Opportunity</button></div><hr>'+form(True)+form(False)+'<p>Looking for personal advisory? <a href="https://robertritch.com/">Visit RobertRitch.com</a>.</p></section>')
    t,d,b=pages['thank-you']
    pages['thank-you']=('Inquiry Submitted','Next steps after a Ritch Ventures business inquiry.',b.replace('Applications are reviewed before a conversation or calendar access is offered. There is no automatic appointment.','Business inquiries are reviewed before a conversation is offered. No appointment is automatically scheduled.'))
    t,d,b=pages['privacy']
    b=b.replace('Effective date: October 8, 2026','Updated: October 10, 2026').replace('Ritch Ventures collects the information you choose to submit through an advisory application or acquisition inquiry. This includes your name, email, company, website, business stage or industry, approximate revenue and your description of the situation, objectives, exit preference and timing.','Ritch Ventures collects information you choose to submit through a business opportunity or acquisition inquiry. This includes your name, email, phone where requested, company, website, inquiry topic or industry, situation, exit preference and timing.').replace('For the intended Netlify production website, Netlify processes and stores submissions and sends configured notifications.','On the Netlify-hosted website, Netlify processes and stores enabled form submissions. Notifications are configured by the website operator.')
    b=b.replace('<div class="privacy-review notice"><strong>Temporary preview:</strong> these forms do not send or store inquiries. Production processing and the responsible legal entity must be confirmed before launch.</div>','')
    pages['privacy']=(t,d,b)
    t,d,b=pages['404']
    pages['404']=(t,d,b.replace('Explore advisory, acquisitions, businesses and resources from the main website.','Explore acquisitions, business development, portfolio management and business relationships from the main website.'))

def form(acq):
    field=baseline_content.field
    prefix='acq' if acq else 'biz'; name='acquisition-inquiry' if acq else 'business-opportunity';kind='acquisition' if acq else 'business'
    common=field(prefix,'first-name','First name',limit=100,autocomplete='given-name')+field(prefix,'last-name','Last name',limit=100,autocomplete='family-name')+field(prefix,'email','Email','email',limit=254,autocomplete='email')+field(prefix,'phone','Phone','tel',required=False,limit=50,autocomplete='tel')+field(prefix,'company','Company',required=acq,limit=200,autocomplete='organization')+field(prefix,'website','Website','url',required=False,limit=500)
    if acq:
        body=common+field(prefix,'industry','Industry',limit=200)+field(prefix,'transaction-reason','Reason for considering a transaction','textarea',limit=2000)+field(prefix,'exit-preference','Full or partial exit preference',options=['Full exit','Partial exit','Open to discussing either'])+field(prefix,'desired-timing','Desired timing',limit=200)+field(prefix,'situation','Brief description of the situation','textarea',limit=5000)
        title='Acquisition Inquiry';intro='Share an initial summary. Do not submit confidential financial documents through this form. Confidentiality arrangements and detailed materials can be discussed later.';button='Send Acquisition Inquiry'
    else:
        body=common+field(prefix,'inquiry-topic','What would you like to discuss?',options=['Investment opportunity','Business development','Distribution relationship','Operating or management relationship','Strategic partnership','Referral opportunity','Other'])+field(prefix,'situation','Briefly describe the opportunity','textarea',limit=5000)+field(prefix,'desired-timing','Desired timing',options=['As soon as practical','Within 3 months','Within 6–12 months','Exploring options'])
        title='Business Opportunity';intro='Tell us about the opportunity and timing. Inquiries are reviewed before an initial conversation is offered. No appointment is automatically scheduled.';button='Submit Inquiry'
    return '<div class="form-panel" id="'+kind+'"><h2>'+title+'</h2><p>'+intro+'</p><form name="'+name+'" method="POST" action="/thank-you/" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="'+name+'"><p hidden><label>Leave this empty<input name="bot-field" tabindex="-1" autocomplete="off"></label></p>'+body+'<p class="small">Your information is used to review and respond to this inquiry. See the <a href="/privacy/">Privacy Policy</a>. Please omit sensitive personal information.</p><button class="button" type="submit">'+button+'</button><p role="status" aria-live="polite" class="notice hidden"></p></form></div>'
